    // 5. New Bin Logic: Discourage opening a new bin unless the current 
    // average residual is poor, or if the item is large and fits poorly elsewhere.
    if is_new_bin {
        // Only consider a new bin if we have many open bins already that are poorly utilized
        if open_bins_count > 0 && mean_residual > 20.0 {
            score += 15.0; 
        } else {
            // Otherwise, heavily penalize opening a new bin to force reuse.
            score += 60.0;
        }
    }

    // 6. Critical Path: If this is the only bin that fits the item, reward it 
    // to prevent skipping it and accidentally forcing a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;
    let cap = bin_capacity as f64;

