    let new_bin_penalty = if bin_residual == bin_capacity {
        (1.0 - progress) * 40.0 + 5.0
    } else {
        0.0
    };

    // Evaluate how well the item fits: 
    // Small post_residual is good (tight fit), but we penalize tiny fragments (< 10) 
    // that are unlikely to accommodate future items.
    let fit_efficiency = if post_res < 10.0 && post_res > 0.0 {
        25.0 // Penalty for creating "dead space" fragments
    } else {
        post_res
    };

    // Lookahead logic: if next_item_size is large, favor bins that leave enough space
    let lookahead_pressure = if next_item_size > 0 {
        let required = next_item_size as f64;
        if post_res < required { 15.0 } else { -5.0 }
