    };

    // Coupling: Use mean_residual to balance load across bins.
    // If the current bin is significantly "fuller" than the mean, prioritize it to keep it that way.
    let load_balance = (post_res - mean_residual).abs() * 0.1;

    // Final score: minimize this value.
    fit_efficiency + new_bin_penalty + lookahead_pressure + load_balance
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
