    if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // 6. Mean Residual Balancing: If the bin's residual is significantly lower than 
    // the global mean, it's a "tight" bin. We want to keep tight bins tight.
    if (post_residual as f64) < mean_residual * 0.8 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
