    // We penalize bins that leave very small gaps (e.g., < 5) which are hard to fill
    let fragmentation_penalty = if post < 5.0 && post > 0.0 { 15.0 / (post + 0.1) } else { 0.0 };

    // Lookahead coupling: If next item is large, favor bins that accommodate it better
    // If next_item_size is 0, we treat it as 0.
    let lookahead_pressure = if next_item_size > 0 {
        let fit_next = (post >= next_item_size as f64) as i32 as f64;
        (1.0 - fit_next) * 20.0
    } else {
