    };

    // Global optimization: If this is the only bin that fits, we must take it (lower score)
    let urgency_bonus = if fitting_bins_count == 1 && !is_new_bin { -30.0 } else { 0.0 };

    // Non-linear coupling: Combine local fit, lookahead, and global state
    let score = post 
        + fragmentation_penalty 
        + lookahead_pressure 
        + new_bin_penalty 
        + urgency_bonus
        + (mean_residual * 0.1);

