    let mut score = post_residual as f64;

    // 1. Fragmentation Avoidance: Refined exponential penalty for "dead zones".
    // If post_residual is small but > 0, it creates unusable slivers. 
    // Increased penalty for better compaction.
    if post_residual > 0 && post_residual < next_item_size {
        let sliver_depth = (next_item_size - post_residual) as f64;
        score += 225.0 + (sliver_depth.powf(1.35) * 9.2);
    }

    // 2. Compaction: Reward exact fits.
    if post_residual == 0 {
        score -= 240.0;
    } else {
        score -= 125.0 / (post_residual as f64 + 0.3).sqrt();
    }

    // 3. Predictive Lookahead: Favor bins that leave residual space matching next_item_size.
    // Boost the reward to prioritize "perfect future fit" scenarios.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 160.0 - (leftover * 0.85);
    }

    // 4. Bin Opening Strategy: Calibrated thresholding for new bins.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = -500.0; // Must open the first bin
        } else {
            // Increased penalty to force reuse of existing bins unless they are highly inefficient.
            score += 265.0 + (mean_residual * 4.8) + (open_bins_count as f64 * 0.55);
        }
    } else {
        // Consolidate space by prioritizing bins with few fitting options (constrained).
        if fitting_bins_count <= 2 {
            score -= 175.0 / (fitting_bins_count as f64 + 0.5);
        }
    }

    // 5. Temporal Horizon: Increased late-stage conservation.
    let progress = step_index as f64 / total_items as f64;
    score += (progress.powf(2.4)) * 240.0;

    // 6. Variance Control: Penalize deviations from the mean residual.
    // Tighter constraint on "bloat" to maintain a uniform bin profile.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 1.35;

    if post_residual as f64 > mean_residual * 1.1 {
        score += 110.0;
    }

    // 7. Adaptive Predictive Weight:
    // If next item is large, prioritize minimizing the "gap" to exactly fit it.
    // If next item is small, prioritize packing density to prevent fragmentation.
    if next_item_size > (bin_capacity / 2) {
        let fit_proximity = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += fit_proximity * 2.15;
    } else if next_item_size > 0 {
        // Higher weight on small items to ensure they occupy the tightest possible slivers.
        score += (post_residual as f64) * 0.65;
    }

    score
}

