    let progress = step_index as f64 / total_items as f64;

    // 1. Refined Fragmentation Avoidance: Target sliver depth with parabolic penalty
    if post_residual > 0 && post_residual < next_item_size {
        let sliver_depth = (next_item_size - post_residual) as f64;
        score += 440.0 + (sliver_depth.powf(1.85) * 22.4);
    }

    // 2. Compaction: Enhanced exact-fit reward with residual density scaling
    if post_residual == 0 {
        score -= 615.0;
    } else {
        score -= 285.0 / (post_residual as f64 + 0.15).powf(0.85);
    }

    // 3. Predictive Lookahead: Favor bin states that leave optimal slack for subsequent items
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 380.0 - (leftover * 2.1) + (if leftover < 6.0 { 190.0 } else { 0.0 });
    }

    // 4. Bin Opening Strategy: Dynamic thresholding based on bin_residual saturation
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = -3200.0;
        } else {
            let pressure = (mean_residual.max(1.0)) * 9.8;
            let late_game_scaling = 1.0 + (progress.powf(3.0) * 1.5);
            score += 850.0 + pressure + (open_bins_count as f64 * 1.8 * late_game_scaling);
        }
    } else {
        // Consolidate space by penalizing bins that are "too empty" relative to global mean
        if post_residual > (mean_residual * 1.4) as u32 {
            score += 150.0;
        }
        if fitting_bins_count <= 3 {
            score -= 420.0 / (fitting_bins_count as f64 + 0.2).powf(0.95);
        }
    }

    // 5. Temporal Horizon: Accelerated late-game packing intensity
    score += (progress.powf(5.0)) * 820.0;

    // 6. Variance Control: Tighten residual distribution around the moving mean
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 2.85;

    if post_residual as f64 > mean_residual * 1.25 {
        score += 310.0;
    }

    // 7. Adaptive Predictive Weight: Differentiate strategy for large vs small items
    let large_threshold = (bin_capacity as f64 * 0.55) as u32;
    if next_item_size > large_threshold {
        let fit_proximity = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += fit_proximity * 5.5;
    } else if next_item_size > 0 {
        // Higher density requirement for small items to prevent early fragmentation
        score += (post_residual as f64) * 1.75;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best Fit).
    let mut score = post;

    // Penalty for leaving "dead space": small residuals that are unlikely to fit future items.
    // We penalize post_residuals that are smaller than the smallest possible item size (10).
    if post > 0.0 && post < 10.0 {
        score += 20.0 * (1.0 - post / 10.0);
    }

    // Lookahead logic: if we know the next item, reward bins that can accommodate it.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0; // Reward bins that keep the next item viable
        } else {
            score += 5.0;  // Penalty if current placement blocks the next item
        }
    }

    // Dynamic pressure: As the stream progresses, favor packing tighter to minimize new bin openings.
    // We use mean_residual to gauge global fragmentation.
    score += (mean_residual - post) * progress * 2.0;

    // New Bin Logic: Only open a new bin if the current fit is extremely poor (large post_residual).
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the average fill is decent.
        // This acts as a dampener to prevent excessive bin creation early on.
        score += 15.0 + (progress * 10.0) + (open_bins_count as f64 * 0.5);
    } else {
        // If it's a tight fit (less than 5 remaining), give it a strong bonus to finalize the bin.
        if post < 5.0 {
            score -= 10.0;
        }
    }

    score
}

