    let progress = step_index as f64 / total_items as f64;

    // 1. Refined Fragmentation: Enhanced penalty for slivers that kill future packing efficiency
    if post_residual > 0 && post_residual < next_item_size {
        let sliver_gap = (next_item_size - post_residual) as f64;
        score += 720.0 + (sliver_gap.powf(2.25) * 18.2);
    }

    // 2. Compaction: Non-linear reward for tight packing
    if post_residual == 0 {
        score -= 980.0;
    } else {
        score -= 420.0 / (post_residual as f64 + 0.08).powf(0.95);
    }

    // 3. Predictive Lookahead: Favor bins leaving specific residual for next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 580.0 - (leftover * 3.1) + (if leftover < 2.0 { 310.0 } else { 0.0 });
    }

    // 4. Dynamic Bin Opening: Adaptive thresholding to prevent premature creation
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = -4800.0;
        } else {
            let density_factor = (mean_residual / bin_capacity as f64).clamp(0.15, 0.65);
            let late_game_penalty = if progress > 0.7 { 1800.0 + (progress * 1500.0) } else { 0.0 };
            score += 1350.0 + (mean_residual * 9.2) + (open_bins_count as f64 * 2.8 * (1.0 + progress.powf(2.8))) + (late_game_penalty / density_factor);
        }
    } else {
        // Consolidate space by prioritizing bins with few fitting options more aggressively
        if fitting_bins_count <= 6 {
            score -= 780.0 / (fitting_bins_count as f64 + 0.2).powf(0.98);
        }
    }

    // 5. Temporal Horizon: Aggressive late-game compaction
    score += (progress.powf(5.8)) * 1450.0;

    // 6. Variance Control: Penalize deviations to keep residual distribution uniform
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 4.6;

    if post_residual as f64 > mean_residual * 1.25 {
        score += 550.0;
    }

    // 7. Adaptive Weighting: Differentiate strategy based on next item size
    let large_threshold = (bin_capacity as f64 * 0.65) as u32;
    if next_item_size > large_threshold {
        let fit_proximity = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += fit_proximity * 8.2;
    } else if next_item_size > 0 {
        score += (post_residual as f64) * 2.6;
    }

    score
}

