    let post_res = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1-9 range is often wasted)
    // A quadratic penalty on small post_residuals discourages "fragmentation"
    let fragmentation_penalty = if post_residual > 0 && post_residual < 10 {
        (10.0 - post_res).powi(2) * 5.0
    } else {
        0.0
    };

    // Use lookahead to favor bins that leave room for the next item
    let lookahead_fit = if next_item_size > 0 && post_residual >= next_item_size {
        -50.0 * (1.0 - progress)
    } else if next_item_size > 0 {
        20.0 * progress
    } else {
        0.0
    };

    // Dynamic threshold: As stream progresses, become more aggressive at packing tightly (Best-Fit)
    // and less willing to open new bins.
    let tightness_bonus = (post_res / bin_capacity as f64) * 20.0 * (1.0 - progress);

    // If this is the only fitting bin, penalize the "New Bin" option heavily
    // unless the fit is extremely poor (large post_residual).
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        if fitting_bins_count > 0 {
            // Strong discouragement to open new bin if existing ones work
            500.0 + (progress * 100.0)
        } else {
            // Neutral if no other options exist
            0.0
        }
    } else {
        0.0
    };

    // Global pressure: If many bins are open, favor filling existing bins to consolidate
    let consolidation_pressure = (open_bins_count as f64) * 2.0;

    post_res + fragmentation_penalty + lookahead_fit + new_bin_penalty + consolidation_pressure - tightness_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Refined Fragmentation: Penalize small gaps that impede future large items
    if post_residual > 0 && post_residual < next_item_size {
        let sliver_gap = (next_item_size - post_residual) as f64;
        score += 750.0 + (sliver_gap.powf(2.3) * 19.5);
    }

    // 2. Compaction: Reward tighter packing with a sharper non-linear curve
    if post_residual == 0 {
        score -= 1050.0;
    } else {
        score -= 440.0 / (post_residual as f64 + 0.1).powf(0.96);
    }

    // 3. Predictive Lookahead: Favor bins leaving specific residual for next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 620.0 - (leftover * 3.4) + (if leftover < 2.5 { 350.0 } else { 0.0 });
    }

    // 4. Dynamic Bin Opening: Tighten thresholding against early bin bloat with density awareness
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = -5200.0;
        } else {
            let density_factor = (mean_residual / bin_capacity as f64).clamp(0.15, 0.8);
            let late_game_penalty = if progress > 0.7 { 2100.0 + (progress * 1800.0) } else { 0.0 };
            score += 1500.0 + (mean_residual * 10.5) + (open_bins_count as f64 * 3.2 * (1.0 + progress.powf(2.6))) + (late_game_penalty / density_factor);
        }
    } else {
        // Consolidate space by prioritizing bins with few fitting options
        if fitting_bins_count <= 14 {
            score -= 850.0 / (fitting_bins_count as f64 + 0.3).powf(0.99);
        }
    }

    // 5. Temporal Horizon: Aggressive late-game compaction
    score += (progress.powf(6.0)) * 1800.0;

    // 6. Variance Control: Penalize deviations to keep residual distribution compact
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 5.2;

    if post_residual as f64 > mean_residual * 1.2 {
        score += 700.0;
    }

    // 7. Adaptive Weighting: Differentiate strategy based on next item size
    let large_threshold = (bin_capacity as f64 * 0.70) as u32;
    if next_item_size > large_threshold {
        let fit_proximity = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += fit_proximity * 9.0;
    } else if next_item_size > 0 {
        // Penalize excess residual more heavily for small items to maintain high density
        score += (post_residual as f64) * 2.9;
    }

    score
}

