    let mut score = post_residual as f64;

    // 1. Base penalty for creating "dead space" (Best-Fit principle)
    // We favor smaller post_residuals (tighter packing).
    score += (post_residual as f64).powf(1.1);

    // 2. Harmonic Class Logic: Penalize residuals that cannot fit common item sizes
    // We penalize residuals in the range (0, 10) as they are likely to become unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 3. Lookahead Logic: If the next item can fit in the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 4. Fitting Constraint: If this is the only bin that fits the item, reward it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 5. New Bin Threshold: Discourage opening a new bin unless the current mean_residual is too high.
    // If we are considering an empty bin (bin_residual == bin_capacity), penalize it 
    // unless the average bin is already quite full.
    if bin_residual == bin_capacity {
        if mean_residual > 20.0 {
            score += 15.0;
        } else {
            score += 80.0; // Strong penalty for opening new bins early
        }
    }

    // 6. Progressive scaling: As we approach the end of the stream, tighten packing requirements.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

