    // 1. Penalize "Dead Space" (residual gaps too small for any likely future item).
    // Items are 10-80, so a residual < 10 is effectively dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Best-Fit logic: punish large post_residuals more heavily to keep bins tight.
    score += post_residual as f64 * 0.5;

    // 3. Lookahead synergy: If the next item fits perfectly in this bin's post_residual, 
    // reward this bin heavily to keep the future item packed.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Global pressure: Penalize opening new bins when many are already open.
    // If this is a new bin (bin_residual == bin_capacity), increase score based on open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Urgency: If this is the last fitting bin, prioritize it to avoid opening a new one,
    // unless the fit is extremely poor (dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Distribution awareness: penalize bins that deviate far from the current mean_residual.
    // This encourages balanced filling across the bin set.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    score
}

