    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Refined Fragmentation: Increased penalty for slivers that prevent future fitting
    // Adjusted exponent and constant to discourage creating "dead-end" tiny gaps
    if post_residual > 0 && post_residual < next_item_size {
        let sliver_gap = (next_item_size - post_residual) as f64;
        score += 980.0 + (sliver_gap.powf(2.9) * 26.5);
    }

    // 2. Compaction: Enhanced non-linear reward for tight packing
    if post_residual == 0 {
        score -= 1800.0;
    } else {
        score -= 720.0 / (post_residual as f64 + 0.05).powf(1.35);
    }

    // 3. Predictive Lookahead: Favor bins leaving specific residual for next_item_size
    // Increased weight on perfect-fit residuals to maximize bin capacity utilization
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 950.0 - (leftover * 4.5) + (if leftover < 1.0 { 750.0 } else if leftover < 3.0 { 300.0 } else { 0.0 });
    }

    // 4. Dynamic Bin Opening: Adaptive thresholding to prevent premature creation
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = -8200.0;
        } else {
            let density_factor = (mean_residual / bin_capacity as f64).clamp(0.01, 1.0);
            let late_game_penalty = if progress > 0.8 { 5000.0 + (progress * 4000.0) } else { 0.0 };
            // Increased penalty for opening new bins when existing ones have sufficient mean capacity
            score += 2800.0 + (mean_residual * 18.5) + (open_bins_count as f64 * 6.5 * (1.0 + progress.powf(6.0))) + (late_game_penalty / density_factor);
        }
    } else {
        // Boost priority for bins that leave little space for the next item, even if not a "perfect" fit
        if fitting_bins_count <= 6 {
            score -= 1500.0 / (fitting_bins_count as f64 + 0.1).powf(1.6);
        }
    }

    // 5. Temporal Horizon: Aggressive late-game compaction
    score += (progress.powf(8.0)) * 3200.0;

    // 6. Variance Control: Penalize deviations to keep residual distribution uniform
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 9.5;

    // Stricter check for residual bloat relative to local packing
    if post_residual as f64 > mean_residual * 1.08 {
        score += 1100.0;
    }

    // 7. Adaptive Weighting: Differentiate strategy based on next item size
    // Using a more conservative threshold to ensure large items have room
    let large_threshold = (bin_capacity as f64 * 0.75) as u32;
    if next_item_size > large_threshold {
        let fit_proximity = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += fit_proximity * 18.0;
    } else if next_item_size > 0 {
        // Penalty for residual that cannot accommodate common small-to-medium items
        score += (post_residual as f64) * 5.2;
    }

    score
}

