    if next_item_size > large_threshold {
        let fit_proximity = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += fit_proximity * 15.2;
    } else if next_item_size > 0 {
        score += (post_residual as f64) * 5.5;
    }

    // 8. Global Residual Pressure: Discourage low-residual bins when many items remain
    if (total_items - step_index) > 50 && post_residual < (bin_capacity / 10) {
        score += 450.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but non-zero (Fragmenting)
    // Small residuals like 1-9 are often "dead space" that cannot fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Synergy: If next item fits in the current post_residual, reward it.
    // This is a form of Best-Fit-Decreasing lookahead optimization.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // Further reward if the residual becomes very tight after the next item
        let post_post = post_residual - next_item_size;
        if post_post < 5 {
            score -= 20.0;
        }
    }

    // 3. Global Density Balancing:
    // If the mean residual is high, we are being too loose. Penalize opening new bins
    // unless the current bin is a very poor fit (high post_residual).
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: base cost + scaling based on mean_residual
        score = 85.0 + (mean_residual * 0.5);
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 4. Harmonic Scaling: Use modulo to identify "ideal" fill levels (e.g., multiples of 25)
    // Multiples of 25 (100, 75, 50, 25) are often the most flexible in bin packing.
    let remainder = post_residual % 25;
    if remainder == 0 {
        score -= 15.0;
    }

    // 5. Progression Weighting:
    // As the stream nears the end, prioritize tightly packing existing bins over keeping new ones open.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
