    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = -7200.0;
        } else {
            let density_factor = (mean_residual / bin_capacity as f64).clamp(0.05, 0.95);
            let late_game_penalty = if progress > 0.75 { 3500.0 + (progress * 3000.0) } else { 0.0 };
            // Increased penalty for opening new bins when many already exist
            score += 2400.0 + (mean_residual * 15.5) + (open_bins_count as f64 * 5.8 * (1.0 + progress.powf(4.2))) + (late_game_penalty / density_factor);
        }
    } else {
        // Encourage using existing bins that are "almost full"
        if fitting_bins_count <= 6 {
            score -= 1250.0 / (fitting_bins_count as f64 + 0.1).powf(1.4);
        }
    }

    // 5. Temporal Horizon: Aggressive late-game compaction
    score += (progress.powf(8.0)) * 2500.0;

    // 6. Variance Control: Penalize deviations to maintain consistent residual state
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 7.5;

    if post_residual as f64 > mean_residual * 1.1 {
        score += 950.0;
    }

    // 7. Adaptive Weighting: Large item handling
    let large_threshold = (bin_capacity as f64 * 0.60) as u32;
    if next_item_size > large_threshold {
        let fit_proximity = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score += fit_proximity * 14.0;
    } else if next_item_size > 0 {
        // Stricter penalty for excess residual when items are small to prevent fragmentation
        score += (post_residual as f64) * 4.8;
    }

    score
}

